package calc

import (
	"math/rand"
	"testing"
)

// Invariant: Clamp(v, lo, hi) stays in [lo, hi] and returns v unchanged when v is already inside.
func TestHuntA_ClampRangeAndIdentity(t *testing.T) {
	r := rand.New(rand.NewSource(1))
	for i := 0; i < 500; i++ {
		lo := r.Intn(50) - 25
		hi := lo + r.Intn(50)
		for _, v := range []int{lo - 1, lo, hi, hi + 1, lo + r.Intn(hi-lo+1)} {
			got := Clamp(v, lo, hi)
			if got < lo || got > hi || (v >= lo && v <= hi && got != v) {
				t.Fatalf("Clamp(%d, %d, %d) = %d", v, lo, hi, got)
			}
		}
	}
}
